INSERT INTO "DevotionPlan" ("id","title","description","image","durationDays","authorName","authorHandle","tag","createdAt") VALUES('dp100','Walking in Faith','A 5-day journey through the fundamentals of faith.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&h=400&q=80',5,'Pastor John','@pastorjohn','Faith','2026-06-05 15:33:56');
INSERT INTO "DevotionPlan" ("id","title","description","image","durationDays","authorName","authorHandle","tag","createdAt") VALUES('dp101','Morning Grace','Start your day with God.','https://images.unsplash.com/photo-1490730141103-6cac27aaab94?auto=format&fit=crop&w=800&h=400&q=80',3,'Sarah Smith','@sarahs','Grace','2026-06-05 15:33:56');
INSERT INTO "DevotionPlan" ("id","title","description","image","durationDays","authorName","authorHandle","tag","createdAt") VALUES('64782835-dc59-431d-a785-ef8984ddefa4','Faith Under Fire','Strengthen your faith and resolve in the midst of challenging circumstances and life storms.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',5,'Apostle Joshua Selman','@joshuaselman','Faith & Resilience','2026-07-07T10:02:54.543+00:00');
INSERT INTO "DevotionPlan" ("id","title","description","image","durationDays","authorName","authorHandle","tag","createdAt") VALUES('92b563ae-e32e-4e32-9785-e47029bf70f2','Excellence in Leadership','Discover the principles of visionary leadership and impact in your generation.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',3,'Pastor Sam Adeyemi','@samadeyemi','Leadership & Success','2026-07-07T10:02:54.985+00:00');
INSERT INTO "DevotionPlan" ("id","title","description","image","durationDays","authorName","authorHandle","tag","createdAt") VALUES('b59d06a5-a41d-4b58-9cb3-257b856c5bdc','Walk in Love','Explore what it truly means to walk in the perfect love of Christ daily.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',3,'Pastor Tunde','@pastortunde','Love & Grace','2026-07-07T10:02:55.056+00:00');
INSERT INTO "DevotionPlan" ("id","title","description","image","durationDays","authorName","authorHandle","tag","createdAt") VALUES('0ac788a7-55e7-4343-a7a7-fda230b6e4b4','Excellence in Leadership','Discover the principles of visionary leadership and impact in your generation.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',3,'Pastor Sam Adeyemi','@samadeyemi','Leadership & Success','2026-07-13 14:09:42');
INSERT INTO "DevotionPlan" ("id","title","description","image","durationDays","authorName","authorHandle","tag","createdAt") VALUES('f78a2056-f00e-4b95-825f-a9a2bfc10a5a','Divine Speed & Purpose','Break through limitations and experience the supernatural acceleration of God in your assignments.','https://images.unsplash.com/photo-1455309036818-60c69d898171?auto=format&fit=crop&w=800&q=80',5,'Apostle Joshua Selman','@joshuaselman','Purpose & Growth','2026-07-13 14:09:42');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('faf63373-4cef-43fe-86dd-9a7fbc782771','64782835-dc59-431d-a785-ef8984ddefa4',1,'The Purpose of Trials','Trials are not meant to destroy you but to refine you. Just as gold is tried in the fire, your faith is purified when subjected to the heat of life''s challenges.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,'2026-07-07T10:02:54.543+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('ffd50b9e-1795-4e7a-b6f6-ec101182f71b','64782835-dc59-431d-a785-ef8984ddefa4',2,'Anchored in the Word','When the winds of adversity blow, only those anchored in the Word of God will remain steadfast. Let the scripture be your ultimate reality.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,'2026-07-07T10:02:54.543+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('34ca8ecd-d844-4a1d-be0d-c2133b6bccbd','64782835-dc59-431d-a785-ef8984ddefa4',3,'The Shield of Faith','Faith is your shield against the fiery darts of the enemy. It is a deliberate choice to trust God''s character even when you cannot trace His hand.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,'2026-07-07T10:02:54.543+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('a7dd9358-b3c2-4f04-862f-50babd371e51','64782835-dc59-431d-a785-ef8984ddefa4',4,'Patience in the Process','God is never in a hurry, but He is always on time. Embrace the process and let patience have its perfect work in your life.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,'2026-07-07T10:02:54.543+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('b1e743ee-cae1-498b-a81b-44853a719d89','64782835-dc59-431d-a785-ef8984ddefa4',5,'Emerging Victorious','You will come out of this fire without the smell of smoke. The same situation meant to break you will be the testimony of your rising.','https://images.unsplash.com/photo-1504052434569-70ad5836ab65?auto=format&fit=crop&w=800&q=80',20,0,'2026-07-07T10:02:54.543+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('9652045b-511f-4361-a7fe-ffd47bcb8278','92b563ae-e32e-4e32-9785-e47029bf70f2',1,'The Mind of a Leader','Leadership begins in the mind. You cannot lead people to a place you have not visited in your imagination and thinking.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',25,10,'2026-07-07T10:02:54.985+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('17cd5c73-69a6-41f5-9588-eb1b324ca6ee','92b563ae-e32e-4e32-9785-e47029bf70f2',2,'Service Above Self','True leadership is not about being served but about serving others. The greatest among you must be a servant.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',25,1,'2026-07-07T10:02:54.985+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('20c407ea-1847-48d0-b4c9-ef272b0d0274','92b563ae-e32e-4e32-9785-e47029bf70f2',3,'Empowering Others','A successful leader is one who reproduces their success in others. Your legacy is measured by the leaders you leave behind.','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80',25,0,'2026-07-07T10:02:54.985+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('64690cdf-6cfd-48b2-a17b-f2676a912bfb','b59d06a5-a41d-4b58-9cb3-257b856c5bdc',1,'Love Defined','God is love. To know God is to know love. We cannot claim to follow Him if our lives do not reflect His unconditional love.',NULL,20,0,'2026-07-07T10:02:55.056+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('115aee78-b303-4c1a-aa59-56b52c5f7218','b59d06a5-a41d-4b58-9cb3-257b856c5bdc',2,'Love in Action','Love is patient, love is kind. It does not envy, it does not boast. Action validates the authenticity of our love.',NULL,20,0,'2026-07-07T10:02:55.056+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('d59785dd-d40b-43eb-b974-0af8d07d63b5','b59d06a5-a41d-4b58-9cb3-257b856c5bdc',3,'Love Conquers All','Perfect love casts out fear. When you operate in the love of Christ, every fear of tomorrow or failure is eradicated.',NULL,20,0,'2026-07-07T10:02:55.056+00:00','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('f9a457c6-b098-44f7-acc1-fc02bcfec50e','0ac788a7-55e7-4343-a7a7-fda230b6e4b4',1,'The Mind of a Leader','Leadership begins in the mind. You cannot lead people to a place you have not visited first in your own imagination, vision, and thinking. A true leader must break free from past limitations, paradigms of lack, and cultural constraints to see things from a dimension of possibilities. Your leadership capacity is strictly defined by your mental model. Spend time upgrading your mind through strategic learning, meditation on global principles, and listening to the blueprint of heaven for your generation.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',25,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('3d06d37b-91db-4f0b-9dc2-968f63edf60c','0ac788a7-55e7-4343-a7a7-fda230b6e4b4',2,'Service Above Self','True leadership is never about status, titles, or being served; it is entirely about serving others with excellence. The corporate world teaches power dynamics, but the kingdom teaches service dynamics. The greatest among you must be the servant of all. When your primary motivation shifts from personal gain to adding undeniable value to the lives of those you lead, you unlock a supernatural level of influence and respect that money cannot buy.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',25,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('9c15f919-9eda-4560-a8d9-4ca295d252d1','0ac788a7-55e7-4343-a7a7-fda230b6e4b4',3,'Empowering Others','A highly successful leader is one who reproduces their success, wisdom, and core values in others. Your ultimate legacy as a leader is not measured by the number of followers you gather, but by the quality of leaders you successfully train, develop, and leave behind. Shift your focus from personal performance to institutional mentorship. Build platforms that empower the next generation to stand on your shoulders and excel far beyond your reach.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',25,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('dd9b79b9-43b2-49e2-aca5-ca036e7b124c','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',1,'The Blueprint of Purpose','Before you were formed in your mother''s womb, God knew you, sanctified you, and ordained you for a specific purpose. True fulfillment in life cannot be found in material acquisition or public applause; it is found exclusively in discovering and executing the divine blueprint written concerning you in the books of heaven. Take time to strip away societal expectations and seek the Lord in prayer to clarify your specific calling and assignment for this season.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('8faf9cd3-e3d4-49fc-801a-1b4f3b779665','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',2,'Supernatural Acceleration','When the hand of the Lord comes upon a man, he is empowered to outrun the chariots of Ahab. Divine speed is not a product of frantic human hustle or manipulation; it is the supernatural consequence of the Holy Spirit backing your life. God can compress time and compress seasons, giving you results in a single month that normally take men a decade to achieve. Align your heart with His will and watch Him accelerate your progress.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('a978ecc5-9774-4beb-b3c6-d8e38c8f1f4b','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',3,'Eliminating Distractions','The enemy of great focus is not always bad things, but good things that have nothing to do with your current assignment. To experience true momentum and speed, you must learn to boldly say "No" to peripheral opportunities that drain your spiritual energy and time. Lay aside every weight and the sins that easily beset you, keeping your eyes completely fixed on the goal ahead. Streamline your routines, your circles, and your focus to match the magnitude of your vision.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('a6240220-4f26-48cd-aa1b-3a561b1d4024','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',4,'The Power of Divine Alignment','Connection determines direction. Who you walk with, listen to, and submit to will drastically alter the speed of your destiny. Walking in alignment means partnering with the right spiritual cover, cultivating relationships with destiny helpers, and maintaining a pure posture before God. When your character aligns with heaven''s laws, structural blockages break away naturally, clearing a straight, highway-like path for your immediate elevation.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
INSERT INTO "DevotionDay" ("id","planId","dayNumber","title","bodyText","image","pointsEarned","likesCount","createdAt","videoUrl") VALUES('332d04e3-f6fc-4ed0-9598-a1aa843192ae','f78a2056-f00e-4b95-825f-a9a2bfc10a5a',5,'Sustaining Momentum','Reaching a peak is one thing, but staying there requires a completely different level of spiritual discipline. To sustain the momentum of divine speed, your secret place of prayer, word study, and worship must remain completely non-negotiable. Success must never breed complacency or pride in your heart. Stay small in your own eyes, continuously give all the glory back to the Father, and remain a teachable vessel ready for the next instruction.','https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=800&q=80',30,0,'2026-07-13 14:09:42','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=800&q=80');
